WITH profit_by_shift AS (SELECT wsit.web_site_id, td.t_shift, SUM(ws.ws_net_profit) AS shift_profit, sm.sm_type FROM web_sales ws JOIN time_dim td ON ws.ws_sold_time_sk = td.t_time_sk JOIN ship_mode sm ON ws.ws_ship_mode_sk = sm.sm_ship_mode_sk JOIN web_site wsit ON ws.ws_web_site_sk = wsit.web_site_sk WHERE td.t_hour BETWEEN 8 AND 17 GROUP BY wsit.web_site_id, td.t_shift, sm.sm_type) SELECT web_site_id, t_shift, shift_profit, sm_type, CASE WHEN shift_profit > 200000 THEN 'Very High' WHEN shift_profit > 100000 THEN 'High' ELSE 'Normal' END AS profit_category FROM profit_by_shift ORDER BY shift_profit DESC
